mapper.select:
SELECT r.id, r.project_id AS projectId, p.name AS projectName, r.applicant_id AS applicantId, ap.name AS applicantName, r.target_engineer_id AS targetEngineerId, te.name AS targetEngineerName, r.scope, r.expire_at AS expireAt, r.reason, r.status, r.approver_id AS approverId, av.name AS approverName, r.approved_at AS approvedAt, r.comment, r.created_at AS createdAt, r.updated_at AS updatedAt FROM biz_project_auth_request r LEFT JOIN biz_project p ON r.project_id = p.id LEFT JOIN sys_user ap ON r.applicant_id = ap.id LEFT JOIN sys_user te ON r.target_engineer_id = te.id LEFT JOIN sys_user av ON r.approver_id = av.id
AND r.status = #{query.status}
AND r.project_id = #{query.projectId}
AND r.applicant_id = #{query.applicantId}
ORDER BY r.created_at DESC, r.id DESC
